  }

  .paper {
    flex: 1;
    overflow: auto;
    overscroll-behavior: contain;
    -webkit-overflow-scrolling: touch;
    padding: 4px 12px 12px;
    text-align: center;
    touch-action: pan-x pan-y;
  }

  canvas {
    display: inline-block;
